package dev.codex.remote

// WebView also intercepts local data: loads generated by loadDataWithBaseURL.
// Let its local decoder handle those; every other resource still gets a denial.
internal fun previewLocalResource(scheme: String?) = scheme.equals("data", ignoreCase = true)

internal enum class PreviewRenderPhase { Loading, Visible, Failed }
internal data class PreviewRenderStatus(val phase: PreviewRenderPhase, val code: Int? = null) {
    fun notice(sequence: Long) = when (phase) {
        PreviewRenderPhase.Loading -> "预览内容已获取 · 正在显示 R$sequence…"
        PreviewRenderPhase.Visible -> "预览已显示 · R$sequence"
        PreviewRenderPhase.Failed -> "预览内容已获取，但页面显示失败（错误码 ${code ?: "未知"}），请刷新或查看内置示例"
    }
}
